function step6_final_results_analysis()
%STEP6_FINAL_RESULTS_ANALYSIS
%
% Final analysis for the rigorous AR(5) backtest.
%
% IMPORTANT:
% This file reads the results generated by:
%
%   step5_final_master_backtest.m
%
% Therefore the prediction metrics, trading metrics, trade count,
% equity curve and drawdown are calculated consistently from the
% same rigorous backtest output.
%
% This file does NOT retrain the model.
%
% It does NOT modify the test predictions.
%
% It only analyzes the final untouched test results.
%
% Academic research/backtesting prototype only.

clc;
close all;

fprintf('\n============================================================\n');
fprintf(' [STEP 6] FINAL RIGOROUS RESULTS ANALYSIS\n');
fprintf('============================================================\n\n');

%% ========================================================================
% 1. PATHS
% =========================================================================

thisFile = mfilename('fullpath');

if isempty(thisFile)

    srcDir = pwd;

else

    srcDir = fileparts(thisFile);

end

projectDir = fileparts(srcDir);

resultsDir = ...
    fullfile(projectDir,'results');

tablesDir = ...
    fullfile(resultsDir,'tables');

figDir = ...
    fullfile(resultsDir,'figures');

backtestFile = ...
    fullfile( ...
    tablesDir, ...
    'FINAL_MASTER_AR5_RIGOROUS_BACKTEST.csv');

summaryFile = ...
    fullfile( ...
    tablesDir, ...
    'FINAL_MASTER_AR5_RIGOROUS_SUMMARY.csv');

if ~isfile(backtestFile)

    error( ...
        'step6:missingBacktest', ...
        ['Cannot find FINAL_MASTER_AR5_RIGOROUS_BACKTEST.csv. ' ...
         'Run step5_final_master_backtest.m first.']);

end

if ~exist(figDir,'dir')

    mkdir(figDir);

end

%% ========================================================================
% 2. LOAD ROW-BY-ROW FINAL BACKTEST
% =========================================================================

B = readtable( ...
    backtestFile, ...
    'VariableNamingRule','preserve');

fprintf('Loaded final rigorous backtest:\n');

fprintf('Rows: %d\n\n',height(B));

requiredColumns = ...
    { ...
    'Date', ...
    'Close', ...
    'ActualNextDayReturn', ...
    'PredictedNextDayReturn', ...
    'Position', ...
    'Turnover', ...
    'TransactionCost', ...
    'StrategyReturn', ...
    'Equity', ...
    'Drawdown' ...
    };

for k = 1:numel(requiredColumns)

    if ~ismember(requiredColumns{k},B.Properties.VariableNames)

        error( ...
            'step6:missingColumn', ...
            'Required column "%s" is missing from the Step 5 output.', ...
            requiredColumns{k});

    end

end

%% ========================================================================
% 3. EXTRACT DATA
% =========================================================================

dates = B.Date;

if ~isdatetime(dates)

    try

        dates = datetime(dates);

    catch

        error( ...
            'step6:badDate', ...
            'Could not convert the Date column to datetime.');

    end

end

dates = dateshift( ...
    dates, ...
    'start', ...
    'day');

closePrice = ...
    toNumeric(B.Close);

actualReturn = ...
    toNumeric(B.ActualNextDayReturn);

predictedReturn = ...
    toNumeric(B.PredictedNextDayReturn);

position = ...
    toNumeric(B.Position);

turnover = ...
    toNumeric(B.Turnover);

transactionCost = ...
    toNumeric(B.TransactionCost);

strategyReturn = ...
    toNumeric(B.StrategyReturn);

equity = ...
    toNumeric(B.Equity);

drawdown = ...
    toNumeric(B.Drawdown);

%% ========================================================================
% 4. REMOVE INVALID ROWS
% =========================================================================

valid = ...
    ~isnat(dates) & ...
    isfinite(closePrice) & ...
    isfinite(actualReturn) & ...
    isfinite(predictedReturn) & ...
    isfinite(position) & ...
    isfinite(turnover) & ...
    isfinite(transactionCost) & ...
    isfinite(strategyReturn) & ...
    isfinite(equity) & ...
    isfinite(drawdown);

dates = dates(valid);

closePrice = closePrice(valid);

actualReturn = actualReturn(valid);

predictedReturn = predictedReturn(valid);

position = position(valid);

turnover = turnover(valid);

transactionCost = transactionCost(valid);

strategyReturn = strategyReturn(valid);

equity = equity(valid);

drawdown = drawdown(valid);

N = numel(actualReturn);

if N < 10

    error( ...
        'step6:tooLittleData', ...
        'Too few valid final test observations.');

end

%% ========================================================================
% 5. TEST PERIOD
% =========================================================================

fprintf('============================================================\n');
fprintf(' TEST PERIOD\n');
fprintf('============================================================\n');

fprintf('Observations : %d\n',N);

fprintf('Start        : %s\n', ...
    datestr(dates(1),'yyyy-mm-dd'));

fprintf('End          : %s\n\n', ...
    datestr(dates(end),'yyyy-mm-dd'));

%% ========================================================================
% 6. PREDICTION METRICS
% =========================================================================

predictionError = ...
    actualReturn - predictedReturn;

RMSE = ...
    sqrt( ...
    mean( ...
    predictionError.^2, ...
    'omitnan'));

MAE = ...
    mean( ...
    abs(predictionError), ...
    'omitnan');

MSE = ...
    mean( ...
    predictionError.^2, ...
    'omitnan');

R2 = ...
    calculateR2( ...
    actualReturn, ...
    predictedReturn);

directionalAccuracy = ...
    calculateDirectionalAccuracy( ...
    actualReturn, ...
    predictedReturn);

predictionCorrelation = ...
    calculateCorrelation( ...
    actualReturn, ...
    predictedReturn);

fprintf('============================================================\n');
fprintf(' PREDICTION PERFORMANCE\n');
fprintf('============================================================\n');

fprintf('RMSE                 : %.6f\n',RMSE);

fprintf('MAE                  : %.6f\n',MAE);

fprintf('MSE                  : %.6f\n',MSE);

fprintf('R2                   : %.6f\n',R2);

fprintf('Directional accuracy : %.2f%%\n', ...
    directionalAccuracy*100);

fprintf('Prediction correlation: %.4f\n\n', ...
    predictionCorrelation);

%% ========================================================================
% 7. FINAL STRATEGY METRICS
% =========================================================================
%
% We intentionally calculate these from the exact strategy-return
% column saved by Step 5.

initialCapital = 10000;

finalCapital = ...
    equity(end);

strategyReturnPct = ...
    (finalCapital/initialCapital - 1)*100;

dailyMean = ...
    mean(strategyReturn,'omitnan');

dailyStd = ...
    std(strategyReturn,0,'omitnan');

if isfinite(dailyStd) && dailyStd > 0

    sharpe = ...
        sqrt(365)*dailyMean/dailyStd;

else

    sharpe = NaN;

end

downside = ...
    min(strategyReturn,0);

downsideStd = ...
    std(downside,0,'omitnan');

if isfinite(downsideStd) && downsideStd > 0

    sortino = ...
        sqrt(365)*dailyMean/downsideStd;

else

    sortino = NaN;

end

maxDrawdownPct = ...
    min(drawdown)*100;

%% ========================================================================
% 8. WIN RATE
% =========================================================================

active = ...
    position ~= 0;

if any(active)

    winRate = ...
        mean( ...
        strategyReturn(active) > 0, ...
        'omitnan');

else

    winRate = NaN;

end

%% ========================================================================
% 9. PROFIT FACTOR
% =========================================================================

grossProfit = ...
    sum( ...
    strategyReturn(strategyReturn > 0), ...
    'omitnan');

grossLoss = ...
    -sum( ...
    strategyReturn(strategyReturn < 0), ...
    'omitnan');

if grossLoss > 0

    profitFactor = ...
        grossProfit/grossLoss;

else

    profitFactor = Inf;

end

%% ========================================================================
% 10. TRADE COUNT
% =========================================================================
%
% Use the SAME turnover definition as Step 5.
%
% This prevents the old discrepancy where Step 5 and Step 6 reported
% different trade counts.

numberTrades = ...
    sum(turnover > 0);

%% ========================================================================
% 11. SIGNAL COUNTS
% =========================================================================

buySignals = ...
    sum(position == 1);

holdSignals = ...
    sum(position == 0);

sellSignals = ...
    sum(position == -1);

%% ========================================================================
% 12. BUY-AND-HOLD BENCHMARK
% =========================================================================
%
% Buy-and-hold uses the same actual next-day return series.
%
% No transaction costs are applied to the benchmark.

bhReturn = ...
    actualReturn;

bhEquity = ...
    zeros(N,1);

bhEquity(1) = ...
    initialCapital * ...
    (1 + bhReturn(1));

for t = 2:N

    bhEquity(t) = ...
        bhEquity(t-1) * ...
        (1 + bhReturn(t));

end

bhPeak = ...
    cummax(bhEquity);

bhDrawdown = ...
    bhEquity ./ bhPeak - 1;

bhFinalCapital = ...
    bhEquity(end);

bhReturnPct = ...
    (bhFinalCapital/initialCapital - 1)*100;

bhMean = ...
    mean(bhReturn,'omitnan');

bhStd = ...
    std(bhReturn,0,'omitnan');

if isfinite(bhStd) && bhStd > 0

    bhSharpe = ...
        sqrt(365)*bhMean/bhStd;

else

    bhSharpe = NaN;

end

bhMaxDD = ...
    min(bhDrawdown)*100;

%% ========================================================================
% 13. COMPARISON
% =========================================================================

returnDifference = ...
    strategyReturnPct - bhReturnPct;

sharpeDifference = ...
    sharpe - bhSharpe;

drawdownDifference = ...
    maxDrawdownPct - bhMaxDD;

%% ========================================================================
% 14. DISPLAY STRATEGY RESULTS
% =========================================================================

fprintf('============================================================\n');
fprintf(' FINAL STRATEGY RESULTS\n');
fprintf('============================================================\n');

fprintf('Initial capital      : $%.2f\n',initialCapital);

fprintf('Final capital        : $%.2f\n',finalCapital);

fprintf('Strategy return      : %.2f%%\n',strategyReturnPct);

fprintf('Sharpe ratio         : %.4f\n',sharpe);

fprintf('Sortino ratio        : %.4f\n',sortino);

fprintf('Maximum drawdown     : %.2f%%\n',maxDrawdownPct);

fprintf('Win rate             : %.2f%%\n',winRate*100);

fprintf('Profit factor        : %.4f\n',profitFactor);

fprintf('Number of trades     : %d\n',numberTrades);

fprintf('BUY signals           : %d\n',buySignals);

fprintf('HOLD signals          : %d\n',holdSignals);

fprintf('SELL signals          : %d\n\n',sellSignals);

%% ========================================================================
% 15. DISPLAY BUY AND HOLD
% =========================================================================

fprintf('============================================================\n');
fprintf(' BUY-AND-HOLD BENCHMARK\n');
fprintf('============================================================\n');

fprintf('Final capital        : $%.2f\n',bhFinalCapital);

fprintf('Return               : %.2f%%\n',bhReturnPct);

fprintf('Sharpe ratio         : %.4f\n',bhSharpe);

fprintf('Maximum drawdown     : %.2f%%\n\n',bhMaxDD);

%% ========================================================================
% 16. DISPLAY COMPARISON
% =========================================================================

fprintf('============================================================\n');
fprintf(' AR(5) vs BUY-AND-HOLD\n');
fprintf('============================================================\n');

fprintf('Return difference    : %.2f percentage points\n', ...
    returnDifference);

fprintf('Sharpe difference    : %.4f\n', ...
    sharpeDifference);

fprintf('Drawdown difference  : %.2f percentage points\n\n', ...
    drawdownDifference);

%% ========================================================================
% 17. INTERPRETATION
% =========================================================================

fprintf('============================================================\n');
fprintf(' INTERPRETATION\n');
fprintf('============================================================\n');

fprintf('\n');

fprintf(['1. The final test directional accuracy is %.2f%%.\n'], ...
    directionalAccuracy*100);

fprintf(['2. The final test R2 is %.6f.\n'],R2);

fprintf(['3. The AR(5) strategy produced %.2f%% return.\n'], ...
    strategyReturnPct);

fprintf(['4. Buy-and-hold produced %.2f%% return over the same period.\n'], ...
    bhReturnPct);

fprintf(['5. The AR(5) maximum drawdown was %.2f%%.\n'], ...
    maxDrawdownPct);

fprintf(['6. Buy-and-hold maximum drawdown was %.2f%%.\n'], ...
    bhMaxDD);

fprintf('\n');

fprintf(['The results indicate limited out-of-sample predictive strength ' ...
         'for this AR(5) configuration during the final test period.\n']);

fprintf(['The strategy also captured substantially less of the market ' ...
         'movement than the buy-and-hold benchmark during this specific ' ...
         'historical period.\n']);

fprintf(['The lower or higher drawdown should be interpreted separately ' ...
         'from total return; the two strategies have different market ' ...
         'exposure.\n']);

fprintf('\n');

%% ========================================================================
% 18. SIGNAL DISTRIBUTION
% =========================================================================

signalPercentage = ...
    [ ...
    buySignals;
    holdSignals;
    sellSignals ...
    ] ./ N * 100;

signalTable = ...
    table( ...
    {'BUY';'HOLD';'SELL'}, ...
    [buySignals;holdSignals;sellSignals], ...
    signalPercentage, ...
    'VariableNames', ...
    {'Signal','Count','Percentage'});

%% ========================================================================
% 19. SAVE FINAL ANALYSIS TABLE
% =========================================================================

analysisMetric = ...
    { ...
    'TestObservations';
    'TestStart';
    'TestEnd';
    'RMSE';
    'MAE';
    'MSE';
    'R2';
    'DirectionalAccuracy';
    'PredictionCorrelation';
    'InitialCapital';
    'FinalCapital';
    'StrategyReturnPct';
    'Sharpe';
    'Sortino';
    'MaxDrawdownPct';
    'WinRate';
    'ProfitFactor';
    'NumberTrades';
    'BuySignals';
    'HoldSignals';
    'SellSignals';
    'BuyHoldFinalCapital';
    'BuyHoldReturnPct';
    'BuyHoldSharpe';
    'BuyHoldMaxDrawdownPct';
    'ReturnDifferencePercentagePoints';
    'SharpeDifference';
    'DrawdownDifferencePercentagePoints' ...
    };

analysisValue = ...
    [ ...
    N;
    datenum(dates(1));
    datenum(dates(end));
    RMSE;
    MAE;
    MSE;
    R2;
    directionalAccuracy;
    predictionCorrelation;
    initialCapital;
    finalCapital;
    strategyReturnPct;
    sharpe;
    sortino;
    maxDrawdownPct;
    winRate;
    profitFactor;
    numberTrades;
    buySignals;
    holdSignals;
    sellSignals;
    bhFinalCapital;
    bhReturnPct;
    bhSharpe;
    bhMaxDD;
    returnDifference;
    sharpeDifference;
    drawdownDifference ...
    ];

analysisTable = ...
    table( ...
    analysisMetric, ...
    analysisValue, ...
    'VariableNames', ...
    {'Metric','Value'});

writetable( ...
    analysisTable, ...
    fullfile( ...
    tablesDir, ...
    'FINAL_RIGOROUS_RESULTS_ANALYSIS.csv'));

writetable( ...
    signalTable, ...
    fullfile( ...
    tablesDir, ...
    'FINAL_RIGOROUS_SIGNAL_DISTRIBUTION.csv'));

%% ========================================================================
% 20. SAVE MATLAB ANALYSIS FILE
% =========================================================================

save( ...
    fullfile( ...
    tablesDir, ...
    'FINAL_RIGOROUS_RESULTS_ANALYSIS.mat'), ...
    'analysisTable', ...
    'signalTable', ...
    'dates', ...
    'actualReturn', ...
    'predictedReturn', ...
    'position', ...
    'strategyReturn', ...
    'equity', ...
    'drawdown', ...
    'bhEquity', ...
    'bhDrawdown');

%% ========================================================================
% 21. EQUITY CURVE
% =========================================================================

fig = figure( ...
    'Color','w', ...
    'Name','Final Equity Comparison');

plot( ...
    dates, ...
    equity, ...
    'LineWidth',1.6);

hold on;

plot( ...
    dates, ...
    bhEquity, ...
    '--', ...
    'LineWidth',1.4);

grid on;

xlabel('Date');

ylabel('Portfolio Value ($)');

title('Final Untouched Test: AR(5) vs Buy-and-Hold');

legend( ...
    {'AR(5) Strategy','Buy-and-Hold'}, ...
    'Location','best');

saveas( ...
    fig, ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_RESULTS_EQUITY.png'));

close(fig);

%% ========================================================================
% 22. PREDICTION PLOT
% =========================================================================

fig = figure( ...
    'Color','w', ...
    'Name','Prediction Comparison');

plot( ...
    dates, ...
    actualReturn*100, ...
    'LineWidth',1.0);

hold on;

plot( ...
    dates, ...
    predictedReturn*100, ...
    'LineWidth',1.0);

grid on;

xlabel('Date');

ylabel('Return (%)');

title('Actual vs Predicted Next-Day Return');

legend( ...
    {'Actual Return','Predicted Return'}, ...
    'Location','best');

saveas( ...
    fig, ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_RESULTS_PREDICTION.png'));

close(fig);

%% ========================================================================
% 23. DRAWDOWN COMPARISON
% =========================================================================

fig = figure( ...
    'Color','w', ...
    'Name','Drawdown Comparison');

plot( ...
    dates, ...
    drawdown*100, ...
    'LineWidth',1.4);

hold on;

plot( ...
    dates, ...
    bhDrawdown*100, ...
    '--', ...
    'LineWidth',1.2);

grid on;

xlabel('Date');

ylabel('Drawdown (%)');

title('AR(5) vs Buy-and-Hold Drawdown');

legend( ...
    {'AR(5)','Buy-and-Hold'}, ...
    'Location','best');

saveas( ...
    fig, ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_RESULTS_DRAWDOWN.png'));

close(fig);

%% ========================================================================
% 24. SIGNAL DISTRIBUTION PLOT
% =========================================================================

fig = figure( ...
    'Color','w', ...
    'Name','Signal Distribution');

bar( ...
    categorical({'BUY','HOLD','SELL'}), ...
    [buySignals,holdSignals,sellSignals]);

grid on;

xlabel('Signal');

ylabel('Number of Observations');

title('Final Test Signal Distribution');

saveas( ...
    fig, ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_SIGNAL_DISTRIBUTION.png'));

close(fig);

%% ========================================================================
% 25. ACTUAL VS PREDICTED SCATTER
% =========================================================================

fig = figure( ...
    'Color','w', ...
    'Name','Actual vs Predicted Scatter');

scatter( ...
    actualReturn*100, ...
    predictedReturn*100, ...
    25, ...
    'filled');

hold on;

minValue = ...
    min( ...
    [actualReturn;predictedReturn] ...
    ) * 100;

maxValue = ...
    max( ...
    [actualReturn;predictedReturn] ...
    ) * 100;

plot( ...
    [minValue,maxValue], ...
    [minValue,maxValue], ...
    '--', ...
    'LineWidth',1.2);

grid on;

xlabel('Actual Next-Day Return (%)');

ylabel('Predicted Next-Day Return (%)');

title( ...
    sprintf( ...
    'Actual vs Predicted Returns (Correlation = %.4f)', ...
    predictionCorrelation));

saveas( ...
    fig, ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_ACTUAL_VS_PREDICTED.png'));

close(fig);

%% ========================================================================
% 26. FINAL FILE LIST
% =========================================================================

fprintf('\n============================================================\n');
fprintf(' FILES SAVED\n');
fprintf('============================================================\n');

fprintf('%s\n', ...
    fullfile( ...
    tablesDir, ...
    'FINAL_RIGOROUS_RESULTS_ANALYSIS.csv'));

fprintf('%s\n', ...
    fullfile( ...
    tablesDir, ...
    'FINAL_RIGOROUS_SIGNAL_DISTRIBUTION.csv'));

fprintf('%s\n', ...
    fullfile( ...
    tablesDir, ...
    'FINAL_RIGOROUS_RESULTS_ANALYSIS.mat'));

fprintf('%s\n', ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_RESULTS_EQUITY.png'));

fprintf('%s\n', ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_RESULTS_PREDICTION.png'));

fprintf('%s\n', ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_RESULTS_DRAWDOWN.png'));

fprintf('%s\n', ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_SIGNAL_DISTRIBUTION.png'));

fprintf('%s\n', ...
    fullfile( ...
    figDir, ...
    'FINAL_RIGOROUS_ACTUAL_VS_PREDICTED.png'));

fprintf('\n============================================================\n');
fprintf(' [STEP 6 RIGOROUS ANALYSIS COMPLETE]\n');
fprintf('============================================================\n\n');

end


%% =========================================================================
% LOCAL FUNCTION: NUMERIC CONVERSION
% =========================================================================

function x = toNumeric(v)

if isnumeric(v)

    x = double(v(:));

elseif islogical(v)

    x = double(v(:));

elseif iscategorical(v)

    x = str2double(string(v(:)));

elseif isstring(v) || ischar(v)

    x = str2double(string(v(:)));

elseif iscell(v)

    x = str2double(string(v(:)));

else

    try

        x = double(v(:));

    catch

        x = NaN(numel(v),1);

    end

end

end


%% =========================================================================
% LOCAL FUNCTION: R2
% =========================================================================

function value = calculateR2(y,yp)

y = y(:);

yp = yp(:);

valid = ...
    isfinite(y) & ...
    isfinite(yp);

y = y(valid);

yp = yp(valid);

denominator = ...
    sum( ...
    (y-mean(y)).^2);

if denominator <= eps

    value = NaN;

else

    value = ...
        1 - ...
        sum((y-yp).^2) / ...
        denominator;

end

end


%% =========================================================================
% LOCAL FUNCTION: DIRECTIONAL ACCURACY
% =========================================================================

function value = calculateDirectionalAccuracy(actual,predicted)

actual = actual(:);

predicted = predicted(:);

valid = ...
    isfinite(actual) & ...
    isfinite(predicted);

actual = actual(valid);

predicted = predicted(valid);

actualSign = ...
    sign(actual);

predictedSign = ...
    sign(predicted);

value = ...
    mean(actualSign == predictedSign);

end


%% =========================================================================
% LOCAL FUNCTION: CORRELATION
% =========================================================================

function value = calculateCorrelation(x,y)

x = x(:);

y = y(:);

valid = ...
    isfinite(x) & ...
    isfinite(y);

x = x(valid);

y = y(valid);

if numel(x) < 2

    value = NaN;

    return;

end

C = corrcoef(x,y);

if size(C,1) >= 2

    value = C(1,2);

else

    value = NaN;

end

end